        },
        "page_refs": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "实体呈现于哪些页：entity 专写，值=本页目录名（INDEX.json 的 dir）。operation 不写"
        }
      }
    },
    "attribute": {
      "type": "object",
      "required": [
        "name",
        "source_refs"
