          "type": "string",
          "minLength": 1
        },
        "concept_type": {
          "type": "string",
          "enum": [
            "business_entity",
            "operation"
          ],
          "description": "两类：business_entity（名词，可持久化对象）/ operation（动词，对实体的原子动作）。导航/菜单不是概念"
        },
        "description": {
          "type": "string",
          "minLength": 1
        },
        "aliases": {
          "type": "array",
          "items": {
            "type": "string"
          }
